describe('Out-of-Stock Item Cart Addition', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.intercept('GET', '**/api/products', { fixture: 'products.json' }).as('getProducts');
    cy.intercept('POST', '**/api/cart/add', (req) => {
      if (req.body.productId === 'out-of-stock-item') {
        req.reply({
          statusCode: 400,
          body: {
            error: 'Item is out of stock',
            message: 'This product is currently unavailable'
          }
        });
      } else {
        req.reply({
          statusCode: 200,
          body: { success: true, cartId: '123' }
        });
      }
    }).as('addToCart');
    cy.wait('@getProducts');
  });

  it('should display out-of-stock message when adding unavailable item', () => {
    cy.get('[data-testid="product-item"]').contains('Out of Stock Product').click();
    cy.get('[data-testid="add-to-cart-btn"]').click();
    cy.wait('@addToCart');

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Item is out of stock');

    cy.get('[data-testid="error-message"]')
      .should('have.class', 'error-alert');

    cy.get('[data-testid="cart-count"]')
      .should('contain', '0');
  });

  it('should allow adding in-stock items while showing error for out-of-stock items', () => {
    cy.get('[data-testid="product-item"]').contains('Available Product').click();
    cy.get('[data-testid="add-to-cart-btn"]').click();
    cy.wait('@addToCart');

    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'Added to cart');

    cy.get('[data-testid="cart-count"]')
      .should('contain', '1');

    cy.get('[data-testid="product-item"]').contains('Out of Stock Product').click();
    cy.get('[data-testid="add-to-cart-btn"]').click();
    cy.wait('@addToCart');

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Item is out of stock');

    cy.get('[data-testid="cart-count"]')
      .should('contain', '1');
  });

  it('should dismiss error message when user clicks close button', () => {
    cy.get('[data-testid="product-item"]').contains('Out of Stock Product').click();
    cy.get('[data-testid="add-to-cart-btn"]').click();
    cy.wait('@addToCart');

    cy.get('[data-testid="error-message"]')
      .should('be.visible');

    cy.get('[data-testid="error-close-btn"]').click();

    cy.get('[data-testid="error-message"]')
      .should('not.be.visible');
  });

  it('should show out-of-stock badge on product card', () => {
    cy.get('[data-testid="product-item"]')
      .contains('Out of Stock Product')
      .parent()
      .within(() => {
        cy.get('[data-testid="stock-badge"]')
          .should('be.visible')
          .and('contain', 'Out of Stock');
      });

    cy.get('[data-testid="product-item"]')
      .contains('Out of Stock Product')
      .parent()
      .within(() => {
        cy.get('[data-testid="add-to-cart-btn"]')
          .should('be.disabled');
      });
  });
});
